```
uniform float uTime;
uniform vec2 uWaveDirs[5];
uniform float uWaveAmp[5];
uniform float uWaveLen[5];
uniform float uWavePhase[5];
varying vec3 vWorldPos;
varying vec3 vNormal;
varying float vHeight;
varying float vFogDepth;

void main(){
 vec2 p = position.xz;
 float h=0.0; vec2 d=vec2(0.0);
 for(int i=0;i<5;i++){
   float k=6.2831853/uWaveLen[i];
   float omega=sqrt(9.81*k)*0.55;
   vec2 dir=normalize(uWaveDirs[i]);
   float ph=k*dot(dir,p)-omega*uTime+uWavePhase[i];
   h += uWaveAmp[i]*sin(ph);
   d += uWaveAmp[i]*k*dir*cos(ph);
 }
 vec3 pos=vec3(position.x, h, position.z);
 vNormal=normalize(vec3(-d.x,1.0,-d.y));
 vHeight=h;
 vec4 wp=modelMatrix*vec4(pos,1.0);
 vWorldPos=wp.xyz;
 vec4 mv=viewMatrix*wp;
 vFogDepth=-mv.z;
 gl_Position=projectionMatrix*mv;
}
```
